using System;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RandomAllTargetsLightningAction", menuName = "Data/Battle/Battle Actions/Purification Actions/RandomAllTargetsLightning Action")]
public class RandomAllTargetsLightningAction : RandomLightningAction
{
	[Header("Units")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override void CastAmount(int actionAmount, GameObject source)
	{
		CastVariableTimes(actionAmount, currentActiveUnits.GetCurrentActiveUnits().Duplicate(), source);
	}

	public void CastAmountWithActionAndDelayToStart(int actionAmount, GameObject source, float delayToStartCorruptedLightningAction, Action afterLightningAction = null, Action rightAfterLastLightningAction = null, Action beforeDelayAction = null)
	{
		CastVariableTimesWithDelayToStart(actionAmount, currentActiveUnits.GetCurrentActiveUnits().Duplicate(), source, delayToStartCorruptedLightningAction, afterLightningAction, rightAfterLastLightningAction, beforeDelayAction);
	}

	public void CastVariableAndTimesAmount(int timesAmount, int purifyCorruptAmount, GameObject source, Action afterLightningAction = null)
	{
		CastVariableAndTimesAmount(timesAmount, purifyCorruptAmount, currentActiveUnits.GetCurrentActiveUnits().Duplicate(), source, afterLightningAction);
	}

	public void CastVariableAndTimesAmountWithActionAndDelayToStart(int actionAmount, int purifyCorruptAmount, GameObject source, float delayToStartCorruptedLightningAction, Action afterLightningAction = null, Action rightAfterLastLightningAction = null, Action beforeDelayAction = null)
	{
		CastVariableAndTimesAmountWithActionAndDelayToStart(actionAmount, purifyCorruptAmount, currentActiveUnits.GetCurrentActiveUnits().Duplicate(), source, delayToStartCorruptedLightningAction, afterLightningAction, rightAfterLastLightningAction, beforeDelayAction);
	}
}
